I fixed the bug and added tests below, but I haven't run them because I can't run code here.

**Cause:** each share was rounded on its own, so the rounding errors could add up to a wrong total. For example, `100, [1,1,1]` gave `[33,33,33]`, which is 99. The new version does this instead:

1. **Exact numbers:** each weight is read as the short decimal JavaScript shows for it (`String(0.1)` is `"0.1"`) and turned into an exact whole number (BigInt). Values like 0.1 and 0.2 therefore can't cause floating-point errors.
2. **Round down first:** each person gets their exact share rounded down. The leftover (always fewer agorot than there are people) goes one each to the largest fractional parts, with ties going to the earlier person. This also guarantees every share is either the floor or the ceiling of its exact value.

**Two input checks I tightened (beyond your rules):** the existing checks are all still there, plus:
- **Weights:** must be finite numbers. Before, `Infinity` and strings like `"2"` got through and caused wrong results.
- **Total:** must be at most `Number.MAX_SAFE_INTEGER`. Above that, a plain JavaScript number can't hold every whole number exactly, so an exact sum can't be promised.

Tell me if you'd rather keep the old checks exactly as they were.

=== FILE: split-bill.js ===
// Splits a bill (in agorot, a whole number) between people by weights.
//
// Rules:
//  - shares are whole agorot and add up EXACTLY to total;
//  - each share is the floor or the ceiling of its exact share total*w/sum;
//  - leftover agorot go one each to the people with the largest fractional
//    parts of their exact share, ties going to the earlier person.
//
// To avoid floating-point errors, every weight is converted to an exact
// decimal (the shortest decimal that JavaScript prints for it, e.g. 0.1 -> "0.1")
// and all arithmetic is done with BigInt.

// Turns a positive finite number into { digits, exp } so that w = digits * 10^exp exactly
// (using JavaScript's shortest round-trip decimal form of w).
function toDecimal(w) {
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/.exec(String(w));
  if (!m) throw new Error("bad weights");
  const frac = m[2] || "";
  return { digits: BigInt(m[1] + frac), exp: Number(m[3] || 0) - frac.length };
}

function splitBill(total, weights) {
  if (!Number.isInteger(total) || total < 0) throw new Error("bad total");
  if (!Number.isSafeInteger(total)) throw new Error("bad total");
  if (!Array.isArray(weights) || !weights.length || weights.some((w) => !(w > 0))) throw new Error("bad weights");
  if (weights.some((w) => typeof w !== "number" || !Number.isFinite(w))) throw new Error("bad weights");

  // Exact integer weights with a common power-of-ten scale.
  const decs = weights.map(toDecimal);
  const minExp = Math.min(...decs.map((d) => d.exp));
  const W = decs.map((d) => d.digits * 10n ** BigInt(d.exp - minExp));
  const S = W.reduce((a, b) => a + b, 0n);
  const T = BigInt(total);

  // Floor of each exact share, and the remainder (fractional part * S).
  const floors = [];
  const rems = [];
  let given = 0n;
  for (const w of W) {
    const num = T * w;
    const q = num / S;
    floors.push(q);
    rems.push(num % S);
    given += q;
  }

  // Leftover is always less than the number of people.
  const leftover = Number(T - given);
  const order = W.map((_, i) => i).sort((a, b) =>
    rems[a] > rems[b] ? -1 : rems[a] < rems[b] ? 1 : a - b
  );
  for (let k = 0; k < leftover; k++) floors[order[k]] += 1n;

  return floors.map((x) => Number(x));
}

module.exports = { splitBill };
=== END FILE ===
=== FILE: split-bill.test.js ===
const assert = require("node:assert");
const { splitBill } = require("./split-bill");

// Original bug report: rounding each share gave 33+33+33 = 99.
assert.deepStrictEqual(splitBill(100, [1, 1, 1]), [34, 33, 33]);

// Ties go to the earlier person.
assert.deepStrictEqual(splitBill(1, [1, 1]), [1, 0]);
assert.deepStrictEqual(splitBill(2, [1, 1, 1]), [1, 1, 0]);
assert.deepStrictEqual(splitBill(5, [1, 1, 1, 1]), [2, 1, 1, 1]);

// The largest fractional part wins, even if it isn't the first person.
assert.deepStrictEqual(splitBill(10, [1, 2]), [3, 7]); // 3.333, 6.667
assert.deepStrictEqual(splitBill(100, [1, 2, 3]), [17, 33, 50]); // 16.667, 33.333, 50
assert.deepStrictEqual(splitBill(10, [2, 1]), [7, 3]);

// Floating-point weights.
assert.deepStrictEqual(splitBill(10, [0.1, 0.2]), [3, 7]);
assert.deepStrictEqual(splitBill(100, [0.1, 0.2, 0.3]), [17, 33, 50]);
assert.deepStrictEqual(splitBill(2, [0.1, 0.3]), [1, 1]); // exact tie 0.5 / 1.5
assert.deepStrictEqual(splitBill(3, [0.1, 0.1, 0.1]), [1, 1, 1]);
assert.deepStrictEqual(splitBill(1, [0.7, 0.7]), [1, 0]);

// Edge cases.
assert.deepStrictEqual(splitBill(0, [1, 2]), [0, 0]);
assert.deepStrictEqual(splitBill(7, [3]), [7]);
assert.deepStrictEqual(splitBill(1, [1e-300, 1e300]), [0, 1]);
assert.deepStrictEqual(splitBill(4, [5e-324, 5e-324]), [2, 2]);

// Input checks.
assert.throws(() => splitBill(-1, [1]), /bad total/);
assert.throws(() => splitBill(1.5, [1]), /bad total/);
assert.throws(() => splitBill("100", [1]), /bad total/);
assert.throws(() => splitBill(100, []), /bad weights/);
assert.throws(() => splitBill(100, "1,2"), /bad weights/);
assert.throws(() => splitBill(100, [1, 0]), /bad weights/);
assert.throws(() => splitBill(100, [1, -1]), /bad weights/);
assert.throws(() => splitBill(100, [1, NaN]), /bad weights/);
assert.throws(() => splitBill(100, [1, Infinity]), /bad weights/);
assert.throws(() => splitBill(100, [1, "2"]), /bad weights/);

// Property check with a deterministic pseudo-random generator:
// shares sum exactly to total and each is within 1 agora of the exact share.
let seed = 12345;
const rand = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);
for (let t = 0; t < 2000; t++) {
  const total = Math.floor(rand() * 100000);
  const n = 1 + Math.floor(rand() * 8);
  const weights = Array.from({ length: n }, () =>
    rand() < 0.5 ? 1 + Math.floor(rand() * 10) : Math.round(rand() * 1000) / 100 + 0.01
  );
  const shares = splitBill(total, weights);
  const sumW = weights.reduce((a, b) => a + b, 0);
  assert.strictEqual(shares.reduce((a, b) => a + b, 0), total);
  shares.forEach((s, i) => {
    assert.ok(Number.isInteger(s) && s >= 0);
    assert.ok(Math.abs(s - (total * weights[i]) / sumW) < 1 + 1e-6);
  });
}

