I added `formatMinutes` and `freeSlots` and wrote the tests. I couldn't run anything here, so I haven't run the tests. Run them with `node free-slots.test.js`.

**Choices I made:**
- **`formatMinutes`** only accepts whole numbers from 0 to 1439 and throws on anything else. That matches `parseTime`, which also stops at `23:59`.
- **`freeSlots`** also throws if `busy` isn't an array, or if `minLen` isn't a number of 0 or more.
- **Zero-length gaps** are never returned, even when `minLen` is 0. So two busy ranges that touch don't produce an empty slot between them.

=== FILE: time-range.js ===
// "HH:MM" <-> minutes since midnight, and "HH:MM-HH:MM" ranges.
function parseTime(s) {
  const m = /^(\d{2}):(\d{2})$/.exec(String(s).trim());
  if (!m || Number(m[1]) > 23 || Number(m[2]) > 59) throw new Error("bad time: " + s);
  return Number(m[1]) * 60 + Number(m[2]);
}
function parseRange(s) {
  const parts = String(s).split("-");
  if (parts.length !== 2) throw new Error("bad range: " + s);
  const start = parseTime(parts[0]), end = parseTime(parts[1]);
  if (end <= start) throw new Error("range ends before it starts: " + s);
  return { start, end };
}
// Minutes since midnight -> "HH:MM" (zero-padded).
function formatMinutes(m) {
  if (!Number.isInteger(m) || m < 0 || m > 23 * 60 + 59) throw new Error("bad minutes: " + m);
  const h = Math.floor(m / 60), min = m % 60;
  return String(h).padStart(2, "0") + ":" + String(min).padStart(2, "0");
}
module.exports = { parseTime, parseRange, formatMinutes };
=== END FILE ===
=== FILE: free-slots.js ===
// Free gaps inside a day, given a list of busy "HH:MM-HH:MM" ranges.
const { parseTime, parseRange, formatMinutes } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen) {
  if (!Array.isArray(busy)) throw new TypeError("busy must be an array");
  const start = parseTime(dayStart), end = parseTime(dayEnd);
  if (end <= start) throw new Error("day ends before it starts: " + dayStart + "-" + dayEnd);
  if (typeof minLen !== "number" || !Number.isFinite(minLen) || minLen < 0) {
    throw new Error("bad minLen: " + minLen);
  }

  // Parse everything first so any bad string throws, then clip to the day.
  const ranges = busy
    .map(parseRange)
    .map(r => ({ start: Math.max(r.start, start), end: Math.min(r.end, end) }))
    .filter(r => r.end > r.start)
    .sort((a, b) => a.start - b.start);

  const result = [];
  let cursor = start;
  for (const r of ranges) {
    if (r.start > cursor) {
      if (r.start - cursor >= minLen) result.push(formatMinutes(cursor) + "-" + formatMinutes(r.start));
    }
    if (r.end > cursor) cursor = r.end; // merges overlapping/touching ranges
  }
  if (end > cursor && end - cursor >= minLen) {
    result.push(formatMinutes(cursor) + "-" + formatMinutes(end));
  }
  return result;
}

module.exports = { freeSlots };
=== END FILE ===
=== FILE: index.js ===
