const { parseTime, parseRange, formatMinutes } = require("./time-range");
const { freeSlots } = require("./free-slots");
module.exports = { parseTime, parseRange, formatMinutes, freeSlots };
=== END FILE ===
=== FILE: free-slots.test.js ===
// Run with: node free-slots.test.js
const assert = require("node:assert");
const { freeSlots, formatMinutes } = require("./index");

// formatMinutes
assert.strictEqual(formatMinutes(0), "00:00");
assert.strictEqual(formatMinutes(545), "09:05");
assert.strictEqual(formatMinutes(1439), "23:59");
assert.throws(() => formatMinutes(1440), /bad minutes/);
assert.throws(() => formatMinutes(-1), /bad minutes/);
assert.throws(() => formatMinutes(1.5), /bad minutes/);

// Overlapping and unsorted busy ranges
assert.deepStrictEqual(
  freeSlots(["10:00-11:00", "10:30-12:00", "09:00-09:30"], "08:00", "17:00", 30),
  ["08:00-09:00", "09:30-10:00", "12:00-17:00"]
);
// One range fully inside another
assert.deepStrictEqual(
  freeSlots(["09:00-12:00", "10:00-11:00"], "08:00", "13:00", 0),
  ["08:00-09:00", "12:00-13:00"]
);

// Touching ranges: no zero-length gap between them or at the day start
assert.deepStrictEqual(
  freeSlots(["09:00-10:00", "10:00-11:00"], "09:00", "12:00", 0),
  ["11:00-12:00"]
);
// Busy right up to the day end
assert.deepStrictEqual(freeSlots(["11:00-12:00"], "09:00", "12:00", 0), ["09:00-11:00"]);

// minLen exactly equal to a gap is kept; one more minute drops it
assert.deepStrictEqual(
  freeSlots(["09:00-10:00", "10:45-12:00"], "09:00", "12:00", 45),
  ["10:00-10:45"]
);
assert.deepStrictEqual(freeSlots(["09:00-10:00", "10:45-12:00"], "09:00", "12:00", 46), []);

// Busy ranges partly or entirely outside the day
assert.deepStrictEqual(
  freeSlots(["07:00-09:30", "16:30-18:00", "05:00-06:00", "19:00-20:00"], "08:00", "17:00", 0),
  ["09:30-16:30"]
);
assert.deepStrictEqual(freeSlots(["07:00-18:00"], "08:00", "17:00", 0), []);

// No busy ranges: the whole day is free (if long enough)
assert.deepStrictEqual(freeSlots([], "08:00", "17:00", 60), ["08:00-17:00"]);
assert.deepStrictEqual(freeSlots([], "08:00", "09:00", 61), []);

// Errors
assert.throws(() => freeSlots([], "10:00", "10:00", 0), /day ends before it starts/);
assert.throws(() => freeSlots([], "11:00", "10:00", 0), /day ends before it starts/);
assert.throws(() => freeSlots([], "8:00", "10:00", 0), /bad time/);
assert.throws(() => freeSlots(["09:00-25:00"], "08:00", "17:00", 0), /bad time/);
assert.throws(() => freeSlots(["09:00"], "08:00", "17:00", 0), /bad range/);
assert.throws(() => freeSlots(["10:00-09:00"], "08:00", "17:00", 0), /range ends before it starts/);
assert.throws(() => freeSlots("09:00-10:00", "08:00", "17:00", 0), TypeError);
assert.throws(() => freeSlots([], "08:00", "17:00", -5), /bad minLen/);

console.log("all free-slots tests passed");
=== END FILE ===

